const express = require('express');
const jwt = require('jsonwebtoken');
const crypto = require('crypto');
const fs = require('fs');

const app = express();

// Key management module
class KeyManager {
  constructor() {
    this.publicKey = fs.readFileSync(process.env.JWT_PUBLIC_KEY_PATH || './keys/public.pem', 'utf8');
    this.privateKey = fs.readFileSync(process.env.JWT_PRIVATE_KEY_PATH || './keys/private.pem', 'utf8');
    this.hmacSecret = crypto.randomBytes(64).toString('hex');
    this.keyId = crypto.createHash('sha256').update(this.publicKey).digest('hex').slice(0, 8);
  }

  getAsymmetricVerificationKey() {
    return this.publicKey;
  }

  getSymmetricVerificationKey() {
    return this.hmacSecret;
  }

  getSigningKey() {
    return this.privateKey;
  }

  getInternalSigningKey() {
    return this.hmacSecret;
  }

  getKeyId() {
    return this.keyId;
  }
}

const keyManager = new KeyManager();

// Simple user store with scrypt-hashed passwords.
// In production this would be a database; the important point is that
// credentials are actually verified before issuing a token.
class UserStore {
  constructor() {
    // Map of username -> { salt, hash (hex), roles }
    this.users = new Map();
  }

  _hash(password, salt) {
    return crypto.scryptSync(password, salt, 64);
  }

  addUser(username, password, roles = ['user']) {
    const salt = crypto.randomBytes(16).toString('hex');
    const hash = this._hash(password, salt).toString('hex');
    this.users.set(username, { salt, hash, roles });
  }

  verify(username, password) {
    const record = this.users.get(username);
    if (!record) {
      // Perform a dummy hash to reduce timing side-channel on user existence.
      crypto.scryptSync(password, 'dummy-salt', 64);
      return null;
    }
    const candidate = this._hash(password, record.salt);
    const expected = Buffer.from(record.hash, 'hex');
    if (
      candidate.length !== expected.length ||
      !crypto.timingSafeEqual(candidate, expected)
    ) {
      return null;
    }
    return { username, roles: record.roles };
  }
}

const userStore = new UserStore();
// Seed users from environment (kept minimal). In real deployments load from a DB.
if (process.env.SEED_USER && process.env.SEED_PASSWORD) {
  userStore.addUser(process.env.SEED_USER, process.env.SEED_PASSWORD, ['user']);
}

// Token verification middleware
function verifyToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Missing authorization header' });
  }

  const token = authHeader.slice(7);

  // Decode header to check key ID for rotation support
  const decoded = jwt.decode(token, { complete: true });
  if (!decoded || !decoded.header) {
    return res.status(401).json({ error: 'Invalid token format' });
  }

  // Select verification key and algorithm based on token type
  let verificationKey;
  let permittedAlgorithms;

  if (decoded.header.alg === 'HS256' && decoded.header.typ === 'internal') {
    // Internal service tokens use separate HMAC secret
    verificationKey = keyManager.getSymmetricVerificationKey();
    permittedAlgorithms = ['HS256'];
  } else {
    // External tokens always use RSA
    verificationKey = keyManager.getAsymmetricVerificationKey();
    permittedAlgorithms = ['RS256'];
  }

  const verifyOptions = {
    algorithms: permittedAlgorithms,
    issuer: 'auth-service',
    audience: 'api-service',
    clockTolerance: 30
  };

  try {
    const payload = jwt.verify(token, verificationKey, verifyOptions);
    req.user = payload;
    next();
  } catch (err) {
    if (err.name === 'TokenExpiredError') {
      return res.status(401).json({ error: 'Token expired' });
    }
    return res.status(401).json({ error: 'Invalid token' });
  }
}

// Protected routes
app.get('/api/profile', verifyToken, (req, res) => {
  res.json({
    userId: req.user.sub,
    email: req.user.email,
    roles: req.user.roles || []
  });
});

app.get('/api/admin/users', verifyToken, (req, res) => {
  if (!req.user.roles || !req.user.roles.includes('admin')) {
    return res.status(403).json({ error: 'Insufficient permissions' });
  }
  res.json({ users: [] });
});

app.delete('/api/admin/users/:id', verifyToken, (req, res) => {
  if (!req.user.roles || !req.user.roles.includes('admin')) {
    return res.status(403).json({ error: 'Insufficient permissions' });
  }
  res.json({ deleted: req.params.id });
});

// Token issuance endpoint
app.post('/api/auth/token', express.json(), (req, res) => {
  const { username, password } = req.body;
  if (!username || !password) {
    return res.status(400).json({ error: 'Missing credentials' });
  }

  // Actually verify the supplied credentials before issuing a token.
  const user = userStore.verify(username, password);
  if (!user) {
    return res.status(401).json({ error: 'Invalid credentials' });
  }

  const token = jwt.sign(
    { sub: user.username, email: `${user.username}@example.com`, roles: user.roles },
    keyManager.getSigningKey(),
    {
      algorithm: 'RS256',
      expiresIn: '1h',
      issuer: 'auth-service',
      audience: 'api-service',
      keyid: keyManager.getKeyId()
    }
  );

  res.json({ token });
});

app.listen(3000, () => console.log('Server running on port 3000'));

module.exports = { app, verifyToken };
